 {
 	switch (key) {
-		case 1:
-			Toggle_Drop_Down();
+		default:
+			if (key >= 3) {
+				Select(TopItem + key - 3);
+				Toggle_Drop_Down();
+			}
 			break;
 		case 2:
 			TopItem = (int)Slider->Get_Value();
 			Update_Rows();
 			break;
