-			if (key >= 3) {
-				Select(TopItem + key - 3);
-				Toggle_Drop_Down();
-			}
+		case 1:
+			Toggle_Drop_Down();
 			break;
 	}
 	return(false);
@@ -542,10 +542,10 @@
 // 0x57B2F0
 void UIComboBoxClass::Scroll_To_Selected()
 {
-	if ((int)Items.size() > NumRows && Slider->Is_Enabled()) {
+	if ((int)Items.size() > NumRows) { if (Slider->Is_Enabled()) {
 		TopItem = min((unsigned)Selected, Items.size() - NumRows);
 		TopItem = Unknown_Clamp(TopItem, 0u, Items.size() - NumRows);
-	} else {
+	} else { TopItem = 0; } } else {
 		TopItem = 0;
